87	// ReadSession reads a session from Copilot CLI's storage (JSONL transcript file).
88	func (c *CopilotCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
89		if input.SessionRef == "" {
90			return nil, errors.New("session reference (transcript path) is required")
91		}
92	
93		data, err := os.ReadFile(input.SessionRef)
94		if err != nil {
95			return nil, fmt.Errorf("failed to read transcript: %w", err)
96		}
97	
98		// Parse events for ModifiedFiles; non-fatal if parsing fails since NativeData
99		// is the authoritative session content. ReadSession has no context.Context so
100		// we cannot log here — scanner errors are surfaced by other code paths that
101		// do have context (e.g. ExtractModifiedFilesFromOffset, ExtractPrompts).
102		events, _ := parseEventsFromBytes(data) //nolint:errcheck // best-effort extraction
103		var modifiedFiles []string
104		if len(events) > 0 {
105			modifiedFiles = extractModifiedFilesFromEvents(events)
106		}
107	
108		return &agent.AgentSession{
109			SessionID:     input.SessionID,
110			AgentName:     c.Name(),
111			SessionRef:    input.SessionRef,
112			StartTime:     time.Now(),
113			NativeData:    data,
114			ModifiedFiles: modifiedFiles,
115		}, nil
116	}
117	
118	// WriteSession writes a session to Copilot CLI's storage (JSONL transcript file).
119	func (c *CopilotCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
120		if session == nil {
121			return errors.New("session is nil")
122		}
123	
124		if session.AgentName != "" && session.AgentName != c.Name() {
125			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
126		}
127	
128		if session.SessionRef == "" {
129			return errors.New("session reference (transcript path) is required")
130		}
131	
132		if len(session.NativeData) == 0 {
133			return errors.New("session has no native data to write")
134		}
135	
136		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
137			return fmt.Errorf("failed to write transcript: %w", err)
138		}
139	
140		return nil
141	}
