1	package copilotcli
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"slices"
8		"time"
9	)
10	
11	// HookHost identifies which host format produced a copilot-compatible hook payload.
12	type HookHost string
13	
14	const (
15		HostUnknown    HookHost = "unknown"
16		HostCopilotCLI HookHost = "copilot-cli"
17		HostVSCode     HookHost = "vscode"
18	)
19	
20	// VS Code hookEventName values (from official VS Code docs).
21	// See: https://code.visualstudio.com/docs/copilot/customization/hooks
22	const (
23		VSCodeEventSessionStart     = "SessionStart"
24		VSCodeEventUserPromptSubmit = "UserPromptSubmit"
25		VSCodeEventStop             = "Stop"
26		VSCodeEventPreToolUse       = "PreToolUse"
27		VSCodeEventPostToolUse      = "PostToolUse"
28		VSCodeEventPreCompact       = "PreCompact"
29		VSCodeEventSubagentStart    = "SubagentStart"
30		VSCodeEventSubagentStop     = "SubagentStop"
31	)
32	
33	// vsCodeEventToHookNames maps each VS Code hookEventName to the CLI hook name(s)
34	// that are allowed to carry that event. "Stop" maps to both agent-stop and
35	// session-end because VS Code uses a single Stop event where Copilot CLI
36	// distinguishes the two.
37	var vsCodeEventToHookNames = map[string][]string{
38		VSCodeEventUserPromptSubmit: {HookNameUserPromptSubmitted},
39		VSCodeEventSessionStart:     {HookNameSessionStart},
40		VSCodeEventStop:             {HookNameAgentStop, HookNameSessionEnd},
41		VSCodeEventSubagentStop:     {HookNameSubagentStop},
42		VSCodeEventPreToolUse:       {HookNamePreToolUse},
43		VSCodeEventPostToolUse:      {HookNamePostToolUse},
44		VSCodeEventPreCompact:       {},
45		VSCodeEventSubagentStart:    {},
46	}
47	
48	type hookEnvelope struct {
49		Host           HookHost
50		SessionID      string
51		Prompt         string
52		TranscriptPath string
53		HookEventName  string
54		Source         string
55		InitialPrompt  string
56		StopReason     string
57		Reason         string
58		Timestamp      time.Time
59	}
60	
61	func parseHookEnvelope(data []byte) (*hookEnvelope, error) {
62		if len(data) == 0 {
63			return nil, errors.New("empty hook input")
64		}
65	
66		var raw map[string]json.RawMessage
67		if err := json.Unmarshal(data, &raw); err != nil {
68			return nil, fmt.Errorf("failed to parse hook input: %w", err)
69		}
70	
71		env := &hookEnvelope{
72			Host:           detectHookHost(raw),
73			SessionID:      firstString(raw, "sessionId", "session_id"),
74			Prompt:         firstString(raw, "prompt"),
75			TranscriptPath: firstString(raw, "transcriptPath", "transcript_path"),
76			HookEventName:  firstString(raw, "hookEventName"),
77			Source:         firstString(raw, "source"),
78			InitialPrompt:  firstString(raw, "initialPrompt"),
79			StopReason:     firstString(raw, "stopReason"),
80			Reason:         firstString(raw, "reason"),
81		}
82	
83		ts, err := parseTimestamp(raw["timestamp"])
84		if err != nil {
85			return nil, fmt.Errorf("failed to parse hook input: %w", err)
86		}
87		env.Timestamp = ts
88	
89		if env.Timestamp.IsZero() {
90			env.Timestamp = time.Now()
91		}
92	
93		return env, nil
94	}
95	
96	func detectHookHost(raw map[string]json.RawMessage) HookHost {
97		if isJSONString(raw["hookEventName"]) {
98			return HostVSCode
99		}
100		if isJSONString(raw["transcript_path"]) {
101			return HostVSCode
102		}
103		if isJSONString(raw["timestamp"]) {
104			return HostVSCode
105		}
106		if _, ok := raw["transcriptPath"]; ok {
107			return HostCopilotCLI
108		}
109		if isJSONNumber(raw["timestamp"]) {
110			return HostCopilotCLI
111		}
112		return HostUnknown
113	}
114	
115	func firstString(raw map[string]json.RawMessage, keys ...string) string {
116		for _, key := range keys {
117			value, ok := raw[key]
118			if !ok {
119				continue
120			}
121			var s string
122			if err := json.Unmarshal(value, &s); err == nil {
123				return s
124			}
125		}
126		return ""
127	}
128	
129	func parseTimestamp(raw json.RawMessage) (time.Time, error) {
130		if len(raw) == 0 || string(raw) == "null" {
131			return time.Time{}, nil
132		}
133	
134		var millis int64
135		if err := json.Unmarshal(raw, &millis); err == nil {
136			if millis == 0 {
137				return time.Time{}, nil // Treat epoch as missing — triggers time.Now() fallback.
138			}
139			return time.UnixMilli(millis), nil
140		}
141	
142		var ts string
143		if err := json.Unmarshal(raw, &ts); err != nil {
144			return time.Time{}, fmt.Errorf("unmarshal timestamp string: %w", err)
145		}
146	
147		parsed, err := time.Parse(time.RFC3339Nano, ts)
148		if err != nil {
149			return time.Time{}, fmt.Errorf("parse timestamp %q: %w", ts, err)
150		}
151		return parsed, nil
152	}
153	
154	func isJSONString(raw json.RawMessage) bool {
155		if len(raw) == 0 || raw[0] != '"' {
156			return false
157		}
158		var s string
159		return json.Unmarshal(raw, &s) == nil
160	}
161	
162	func isJSONNumber(raw json.RawMessage) bool {
163		if len(raw) == 0 || raw[0] == 'n' {
164			return false
165		}
166		var n int64
167		return json.Unmarshal(raw, &n) == nil
168	}
169	
170	// validateVSCodeEvent checks whether the hookEventName is consistent with the
171	// CLI hook subcommand that was invoked. Returns true if the event should be
172	// processed, false if it should be silently skipped (mismatch or unknown event).
173	func validateVSCodeEvent(env *hookEnvelope, hookName string) bool {
174		hookEventName := env.HookEventName
175		allowedHooks, known := vsCodeEventToHookNames[hookEventName]
176		if !known {
177			return false
178		}
179		if !slices.Contains(allowedHooks, hookName) {
180			return false
181		}
182	
183		// VS Code overloads "Stop" for both end-of-turn and terminal session-stop
184		// payloads. Route them by reason to avoid ending sessions on ordinary turns.
185		if hookEventName == VSCodeEventStop {
186			isTerminal := isTerminalVSCodeStop(env)
187			switch hookName {
188			case HookNameAgentStop:
189				return !isTerminal
190			case HookNameSessionEnd:
191				return isTerminal
192			}
193		}
194	
195		return true
196	}
197	
198	func isTerminalVSCodeStop(env *hookEnvelope) bool {
199		if env.Reason != "" {
200			return true
201		}
202	
203		switch env.StopReason {
204		case "", "end_turn":
205			return false
206		default:
207			return true
208		}
209	}
