40	// LoadSessionState loads the session state for the given session ID.
41	// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
42	// Stale sessions are automatically deleted by the underlying StateStore.
43	func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
44		store, err := session.NewStateStore(ctx)
45		if err != nil {
46			return nil, fmt.Errorf("failed to create state store: %w", err)
47		}
48	
49		state, err := store.Load(ctx, sessionID)
50		if err != nil {
51			return nil, fmt.Errorf("failed to load session state: %w", err)
52		}
53		return state, nil
54	}
55	
56	// SaveSessionState saves the session state atomically.
57	func SaveSessionState(ctx context.Context, state *SessionState) error {
58		// Validate session ID to prevent path traversal
59		if err := validation.ValidateSessionID(state.SessionID); err != nil {
60			return fmt.Errorf("invalid session ID: %w", err)
61		}
62	
63		stateDir, err := getSessionStateDir(ctx)
64		if err != nil {
65			return fmt.Errorf("failed to get session state directory: %w", err)
66		}
67	
68		if err := os.MkdirAll(stateDir, 0o750); err != nil {
69			return fmt.Errorf("failed to create session state directory: %w", err)
70		}
71	
72		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
73		if err != nil {
74			return fmt.Errorf("failed to marshal session state: %w", err)
75		}
76	
77		stateFile, err := sessionStateFile(ctx, state.SessionID)
78		if err != nil {
79			return fmt.Errorf("failed to get session state file path: %w", err)
80		}
81	
82		// Atomic write: write to temp file, then rename
83		tmpFile := stateFile + ".tmp"
84		if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
85			return fmt.Errorf("failed to write session state: %w", err)
86		}
87		if err := os.Rename(tmpFile, stateFile); err != nil {
88			return fmt.Errorf("failed to rename session state file: %w", err)
89		}
90		return nil
91	}
92	
93	// ListSessionStates returns all session states from the state directory.
94	// This is a package-level function that doesn't require a specific strategy instance.
95	func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
96		store, err := session.NewStateStore(ctx)
97		if err != nil {
98			return nil, fmt.Errorf("failed to create state store: %w", err)
99		}
100	
101		states, err := store.List(ctx)
102		if err != nil {
103			return nil, fmt.Errorf("failed to list session states: %w", err)
104		}
105		return states, nil
106	}
107	
108	// FindMostRecentSession returns the session ID of the most recently interacted session
109	// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
110	// Scoping to the current worktree prevents cross-worktree pollution in log routing.
111	// Falls back to unfiltered search if the worktree path can't be determined.
112	func FindMostRecentSession(ctx context.Context) string {
113		states, err := ListSessionStates(ctx)
114		if err != nil || len(states) == 0 {
115			return ""
116		}
117	
118		// Scope to current worktree to prevent cross-worktree pollution.
119		worktreePath, wpErr := paths.WorktreeRoot(ctx)
120		if wpErr == nil && worktreePath != "" {
121			var filtered []*SessionState
122			for _, s := range states {
123				if s.WorktreePath == worktreePath {
124					filtered = append(filtered, s)
125				}
126			}
127			if len(filtered) > 0 {
128				states = filtered
129			}
130			// If no sessions match the worktree, fall back to all sessions
131		}
132	
133		var best *SessionState
134		for _, s := range states {
135			if s.LastInteractionTime == nil {
136				continue
137			}
138			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
139				best = s
140			}
141		}
142		if best != nil {
143			return best.SessionID
144		}
145	
146		// Fallback: return most recently started session
147		for _, s := range states {
148			if best == nil || s.StartedAt.After(best.StartedAt) {
149				best = s
150			}
151		}
152		if best != nil {
153			return best.SessionID
154		}
155		return ""
156	}
157	
158	// TransitionAndLog runs a session phase transition, applies actions via the
159	// handler, and logs the transition. Returns the first handler error from
160	// ApplyTransition (if any) so callers can surface it. The error is also
161	// logged internally for diagnostics.
162	// This is the single entry point for all state machine transitions to ensure
163	// consistent logging of phase changes.
164	func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
165		oldPhase := state.Phase
166		result := session.Transition(oldPhase, event, ctx)
167		logCtx := logging.WithComponent(goCtx, "session")
168	
169		handlerErr := session.ApplyTransition(goCtx, state, result, handler)
170		if handlerErr != nil {
171			logging.Error(logCtx, "action handler error during transition",
172				slog.String("session_id", state.SessionID),
173				slog.String("event", event.String()),
174				slog.Any("error", handlerErr),
175			)
176		}
177	
178		if result.NewPhase != oldPhase {
179			logging.Info(logCtx, "phase transition",
180				slog.String("session_id", state.SessionID),
181				slog.String("event", event.String()),
182				slog.String("from", string(oldPhase)),
183				slog.String("to", string(result.NewPhase)),
184			)
185		} else {
186			logging.Debug(logCtx, "phase unchanged",
187				slog.String("session_id", state.SessionID),
188				slog.String("event", event.String()),
189				slog.String("phase", string(result.NewPhase)),
190				slog.Any("result", result),
191			)
192		}
193	
194		if handlerErr != nil {
195			return fmt.Errorf("transition %s: %w", event, handlerErr)
196		}
197		return nil
198	}
199	
200	// StoreModelHint writes the LLM model name to a lightweight hint file
201	// (.git/entire-sessions/{session_id}.model) for cross-process persistence.
202	//
203	// Why a separate file instead of SessionState?
204	//
205	// SessionState requires BaseCommit (used for shadow branch naming, checkpoint
206	// writing, doctor classification, etc.) and is only created during TurnStart
207	// when the git repo is fully inspected. Some agents report the model on earlier
208	// hooks that fire as separate CLI processes before TurnStart:
209	//
210	//   - Claude Code sends "model" on SessionStart (before any TurnStart)
211	//   - Gemini CLI sends "llm_request.model" on BeforeModel (after TurnStart,
212	//     so handleLifecycleModelUpdate writes to SessionState directly when it
213	//     exists and only falls back to this hint file otherwise)
214	//
215	// The hint is read by handleLifecycleTurnStart/TurnEnd when event.Model is
216	// empty, passed to InitializeSession, and persisted in state.ModelName. After
217	// that the hint file is redundant — it sits unused until ClearSessionState
218	// removes it alongside the session state file.
219	func StoreModelHint(ctx context.Context, sessionID, model string) error {
220		if err := validation.ValidateSessionID(sessionID); err != nil {
221			return fmt.Errorf("invalid session ID: %w", err)
222		}
223		if model == "" {
224			return nil
225		}
226	
227		stateDir, err := getSessionStateDir(ctx)
228		if err != nil {
229			return fmt.Errorf("failed to get session state directory: %w", err)
230		}
231		if err := os.MkdirAll(stateDir, 0o750); err != nil {
232			return fmt.Errorf("failed to create session state directory: %w", err)
233		}
234	
235		hintFile := filepath.Join(stateDir, sessionID+".model")
236		if err := os.WriteFile(hintFile, []byte(model), 0o600); err != nil {
237			return fmt.Errorf("failed to write model hint file: %w", err)
238		}
239		return nil
240	}
241	
242	// LoadModelHint reads the LLM model name from the hint file for the given session.
243	// Returns empty string if the hint file doesn't exist or can't be read.
244	func LoadModelHint(ctx context.Context, sessionID string) string {
245		if err := validation.ValidateSessionID(sessionID); err != nil {
246			return ""
247		}
248	
249		stateDir, err := getSessionStateDir(ctx)
250		if err != nil {
251			logging.Warn(logging.WithComponent(ctx, "session"), "failed to resolve state dir for model hint",
252				slog.String("session_id", sessionID),
253				slog.Any("error", err))
254			return ""
255		}
256	
257		hintPath := filepath.Join(stateDir, sessionID+".model")
258		data, err := os.ReadFile(hintPath) //nolint:gosec // sessionID is validated above
259		if err != nil {
260			if !os.IsNotExist(err) {
261				logging.Warn(logging.WithComponent(ctx, "session"), "failed to read model hint file",
262					slog.String("path", hintPath),
263					slog.Any("error", err))
264			}
265			return ""
266		}
267		return strings.TrimSpace(string(data))
268	}
269	
270	// ClearSessionState removes the session state file for the given session ID.
271	func ClearSessionState(ctx context.Context, sessionID string) error {
272		// Validate session ID to prevent path traversal
273		if err := validation.ValidateSessionID(sessionID); err != nil {
274			return fmt.Errorf("invalid session ID: %w", err)
275		}
276	
277		stateDir, err := getSessionStateDir(ctx)
278		if err != nil {
279			return fmt.Errorf("failed to get session state directory: %w", err)
280		}
281	
282		// Remove all files for this session (state .json, .model hint, any future hint files).
283		matches, _ := filepath.Glob(filepath.Join(stateDir, sessionID+".*")) //nolint:errcheck // pattern is always valid
284		for _, f := range matches {
285			_ = os.Remove(f)
286		}
287	
288		return nil
289	}
